import { cancelBubble } from '@cetus/utils'
import { Flex, HStack, Skeleton, Text, Tooltip, TypographyProps, VStack } from '@chakra-ui/react'
import React from 'react'

type VTextLabelBoxProps = {
  title: string | JSX.Element
  titleFontSize?: TypographyProps['fontSize']
  value: string | JSX.Element
  valueFontSize?: TypographyProps['fontSize']
  titleColor?: string
  valueColor?: string
  valueTooltip?: string | JSX.Element
  subValue?: string | JSX.Element
  subValueColor?: string
  alignItems?: string
  itemHeight?: string
  isLoading?: boolean
  isTitleLoading?: boolean
  vGap?: string
  whiteSpace?: string
  skeletonStyle?: VTextLabelSkeleton
}

export default function VTextLabelBox(props: VTextLabelBoxProps) {
  const {
    title,
    titleFontSize,
    value,
    valueFontSize,
    titleColor = 'text_paragraph',
    valueColor = 'text_caption',
    vGap = '3px',
    itemHeight,
    valueTooltip,
    subValue,
    subValueColor,
    alignItems,
    isTitleLoading,
    isLoading = false,
    skeletonStyle,
    whiteSpace = 'nowrap'
  } = props

  return isLoading || isTitleLoading ? (
    <VTextLabelSkeleton {...skeletonStyle} {...props} />
  ) : (
    <VStack gap={vGap} alignItems={alignItems ? alignItems : 'start'}>
      <Text color={titleColor} fontSize={titleFontSize ? titleFontSize : '14px'} whiteSpace={whiteSpace}>
        {title}
      </Text>

      <HStack>
        {valueTooltip ? (
          <Tooltip label={valueTooltip} aria-label="Yield" maxW="none" ml="12px" mr="12px">
            <button onClick={e => cancelBubble(e)}>
              <Text cursor="help" textDecoration="underline dotted" fontSize={valueFontSize ? valueFontSize : '14px'} color={valueColor}>
                {value}
              </Text>
            </button>
          </Tooltip>
        ) : (
          <Text whiteSpace={whiteSpace} textAlign="start" wordBreak="break-all" fontSize={valueFontSize ? valueFontSize : '14px'} color={valueColor}>
            {value}
          </Text>
        )}
      </HStack>

      {subValue && (
        <Text fontSize="14px" color={subValueColor ? subValueColor : 'text_paragraph'}>
          {subValue}
        </Text>
      )}
    </VStack>
  )
}

type VTextLabelSkeleton = {
  titleW?: string
  valueW?: string
  subValueW?: string
  titleH?: string
  valueH?: string
  subValueH?: string
}

type VTextLabelSkeletonProps = VTextLabelSkeleton & VTextLabelBoxProps

function VTextLabelSkeleton(props: VTextLabelSkeletonProps) {
  const {
    titleW = '60px',
    valueW = '70px',
    value,
    subValueW = '80px',
    vGap = '3px',
    subValue,
    alignItems,
    itemHeight,
    isTitleLoading = false,
    isLoading = false,
    valueFontSize,
    valueColor,
    subValueColor,
    titleColor = 'text_paragraph',
    title,
    titleFontSize,
    titleH,
    valueH,
    subValueH
  } = props
  return (
    <VStack minH={itemHeight || ''} gap={vGap} alignItems={alignItems ? alignItems : 'start'}>
      {isTitleLoading ? (
        <Flex h={titleH} align="center">
          <Skeleton w={titleW} />
        </Flex>
      ) : (
        <Text color={titleColor} fontSize={titleFontSize ? titleFontSize : '14px'} whiteSpace="nowrap">
          {title}
        </Text>
      )}
      {isLoading && (typeof value === 'string' || React.isValidElement(value)) ? (
        <Flex h={valueH} align="center">
          <Skeleton w={valueW} />
        </Flex>
      ) : (
        <Text fontSize={valueFontSize ? valueFontSize : '14px'} color={valueColor}>
          {value}
        </Text>
      )}
      {isLoading && subValue && typeof subValue === 'string' ? (
        <Flex h={subValueH} align="center">
          <Skeleton w={subValueW} />
        </Flex>
      ) : (
        <Text fontSize="14px" color={subValueColor ? subValueColor : 'text_paragraph'}>
          {subValue}
        </Text>
      )}
    </VStack>
  )
}
